definition:
CREATE OR REPLACE FUNCTION public.add_floor_plan_object(p_floor_plan_id uuid, p_name text, p_shape_id text, p_category floor_object_category, p_x numeric DEFAULT 100, p_y numeric DEFAULT 100, p_rotation numeric DEFAULT 0, p_capacity integer DEFAULT NULL::integer, p_width numeric DEFAULT NULL::numeric, p_height numeric DEFAULT NULL::numeric)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
  v_floor_plan RECORD;
  v_object_id UUID;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.floor_plan.manage', 'merchant.settings.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Get floor plan info
  SELECT fp.*, fp.merchant_id, fp.location_id
  INTO v_floor_plan
  FROM public.floor_plans fp
  WHERE fp.id = p_floor_plan_id
    AND fp.merchant_id = user_merchant_id();
    -- AND fp.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Floor plan not found';
  END IF;

  -- Insert object
  INSERT INTO public.floor_plan_objects (
    floor_plan_id, merchant_id, location_id,
    name, shape_id, category,
    x, y, rotation,
    capacity, width, height
  ) VALUES (
    p_floor_plan_id, v_floor_plan.merchant_id, v_floor_plan.location_id,
    p_name, p_shape_id, p_category,
    p_x, p_y, p_rotation,
    p_capacity, p_width, p_height
  )
  RETURNING id INTO v_object_id;

  RETURN json_build_object(
    'success', true,
    'object_id', v_object_id,
    'name', p_name,
    'shape_id', p_shape_id
  );
END;$function$

CREATE OR REPLACE FUNCTION public.add_order_item_with_course(p_order_id uuid, p_item_name text, p_unit_price numeric, p_quantity integer DEFAULT 1, p_course_number integer DEFAULT NULL::integer, p_menu_item_id uuid DEFAULT NULL::uuid, p_location_exclusive_item_id uuid DEFAULT NULL::uuid, p_item_description text DEFAULT NULL::text, p_category_name text DEFAULT NULL::text, p_cash_price numeric DEFAULT NULL::numeric, p_use_cash_price boolean DEFAULT false, p_selected_size_id uuid DEFAULT NULL::uuid, p_selected_size_name text DEFAULT NULL::text, p_size_price_modifier numeric DEFAULT 0, p_special_instructions text DEFAULT NULL::text, p_modifiers jsonb DEFAULT '[]'::jsonb, p_prep_station text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order RECORD;
  v_course INTEGER;
  v_course_status TEXT;
  v_order_item_id UUID;
  v_effective_price NUMERIC;
  v_modifier_total NUMERIC := 0;
  v_subtotal NUMERIC;
  v_mod JSONB;
BEGIN
  -- Get order and validate
  SELECT o.*, ts.working_course
  INTO v_order
  FROM public.orders o
  LEFT JOIN public.table_sessions ts ON ts.order_id = o.id AND ts.is_active = TRUE
  WHERE o.id = p_order_id
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- Determine course number
  v_course := COALESCE(p_course_number, v_order.working_course, 1);

  -- Check if course is still open
  SELECT status INTO v_course_status
  FROM public.order_courses
  WHERE order_id = p_order_id AND course_number = v_course;

  IF v_course_status IS NOT NULL AND v_course_status != 'open' THEN
    RAISE EXCEPTION 'Cannot add items to course % - it has already been fired', v_course;
  END IF;

  -- Ensure course exists
  PERFORM public.ensure_course_exists(p_order_id, v_course);

  -- Calculate effective price
  v_effective_price := CASE 
    WHEN p_use_cash_price AND p_cash_price IS NOT NULL THEN p_cash_price
    ELSE p_unit_price
  END + COALESCE(p_size_price_modifier, 0);

  -- Calculate modifier total
  FOR v_mod IN SELECT * FROM jsonb_array_elements(p_modifiers)
  LOOP
    v_modifier_total := v_modifier_total + 
      COALESCE((v_mod->>'price_modifier')::NUMERIC, 0) * 
      COALESCE((v_mod->>'quantity')::INTEGER, 1);
  END LOOP;

  -- Calculate subtotal
  v_subtotal := (v_effective_price + v_modifier_total) * p_quantity;

  -- Insert item
  INSERT INTO public.order_items (
    order_id, menu_item_id, location_exclusive_item_id,
    item_name, item_description, category_name,
    unit_price, cash_price,
    selected_size_id, selected_size_name, size_price_modifier,
    quantity, subtotal,
    special_instructions, prep_station,
    course_number
  ) VALUES (
    p_order_id, p_menu_item_id, p_location_exclusive_item_id,
    p_item_name, p_item_description, p_category_name,
    p_unit_price, p_cash_price,
    p_selected_size_id, p_selected_size_name, p_size_price_modifier,
    p_quantity, v_subtotal,
    p_special_instructions, p_prep_station,
    v_course
  )
  RETURNING id INTO v_order_item_id;

  -- Insert modifiers
  FOR v_mod IN SELECT * FROM jsonb_array_elements(p_modifiers)
  LOOP
    INSERT INTO public.order_item_modifiers (
      order_item_id,
      modifier_group_id,
      modifier_item_id,
      modifier_group_name,
      modifier_name,
      price_modifier,
      quantity
    ) VALUES (
      v_order_item_id,
      (v_mod->>'modifier_group_id')::UUID,
      (v_mod->>'modifier_item_id')::UUID,
      v_mod->>'modifier_group_name',
      v_mod->>'modifier_name',
      COALESCE((v_mod->>'price_modifier')::NUMERIC, 0),
      COALESCE((v_mod->>'quantity')::INTEGER, 1)
    );
  END LOOP;

  RETURN json_build_object(
    'success', true,
    'order_item_id', v_order_item_id,
    'course_number', v_course,
    'subtotal', v_subtotal
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.add_to_waitlist(p_location_id uuid, p_party_name text, p_party_size integer, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_preferred_section text DEFAULT NULL::text, p_seating_preference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_quoted_wait_minutes integer DEFAULT NULL::integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
  v_merchant_id UUID;
  v_waitlist_id UUID;
  v_position INTEGER;
  v_calculated_wait INTEGER;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.waitlist.manage', 'location.tables.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Get merchant ID
  v_merchant_id := user_merchant_id();

  -- -- Verify location access
  -- IF NOT p_location_id = ANY(user_location_ids()) THEN
  --   RAISE EXCEPTION 'Location access denied';
  -- END IF;

  -- Get current position in queue
  SELECT COUNT(*) + 1 INTO v_position
  FROM public.waitlist
  WHERE location_id = p_location_id AND status = 'waiting';

  -- Calculate estimated wait if not provided
  IF p_quoted_wait_minutes IS NULL THEN
    v_calculated_wait := public.estimate_wait_time(p_location_id, p_party_size);
  ELSE
    v_calculated_wait := p_quoted_wait_minutes;
  END IF;

  -- Create waitlist entry
  INSERT INTO public.waitlist (
    merchant_id, location_id,
    party_name, party_size, phone, email,
    preferred_section, seating_preference, notes,
    quoted_wait_minutes, estimated_ready_at,
    position_in_queue,
    created_by_staff_id
  ) VALUES (
    v_merchant_id, p_location_id,
    p_party_name, p_party_size, p_phone, p_email,
    p_preferred_section, p_seating_preference, p_notes,
    v_calculated_wait, NOW() + (v_calculated_wait || ' minutes')::INTERVAL,
    v_position,
    user_staff_profile_id()
  )
  RETURNING id INTO v_waitlist_id;

  RETURN json_build_object(
    'success', true,
    'waitlist_id', v_waitlist_id,
    'position', v_position,
    'quoted_wait_minutes', v_calculated_wait,
    'estimated_ready_at', NOW() + (v_calculated_wait || ' minutes')::INTERVAL,
    'party_name', p_party_name
  );
END;$function$

CREATE OR REPLACE FUNCTION public.advance_course(p_session_id uuid, p_fire_course boolean DEFAULT true, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_current_course INTEGER;
  v_total_courses INTEGER;
  v_event_type session_event_type;
BEGIN
  -- Get current course info
  SELECT current_course, total_courses
  INTO v_current_course, v_total_courses
  FROM public.table_sessions
  WHERE id = p_session_id
    AND is_active = TRUE
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Advance course
  v_current_course := v_current_course + 1;

  UPDATE public.table_sessions
  SET current_course = v_current_course, updated_at = NOW()
  WHERE id = p_session_id;

  -- Record event
  v_event_type := CASE v_current_course
    WHEN 1 THEN 'appetizers_fired'::session_event_type
    WHEN 2 THEN 'mains_fired'::session_event_type
    WHEN 3 THEN 'desserts_fired'::session_event_type
    ELSE 'custom'::session_event_type
  END;

  IF p_fire_course THEN
    INSERT INTO public.table_session_events (
      session_id, event_type, notes,
      event_data, triggered_by_staff_id, triggered_by_user_id
    ) VALUES (
      p_session_id, v_event_type, p_notes,
      jsonb_build_object('course_number', v_current_course),
      user_staff_profile_id(), get_my_claim('sub')
    );
  END IF;

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'current_course', v_current_course,
    'total_courses', v_total_courses,
    'is_final_course', v_current_course >= v_total_courses
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_shift_swap(p_request_id uuid, p_manager_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_req record;
BEGIN
    -- 1. Get request details
    SELECT * INTO v_req FROM shift_trade_requests WHERE id = p_request_id;

    IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
    IF v_req.status != 'pending_manager' THEN RAISE EXCEPTION 'Request is not pending approval'; END IF;

    -- 2. Swap the employees on the actual shifts
    -- Assign Requester's Shift -> Recipient
    UPDATE shifts 
    SET employee_id = v_req.recipient_id, status = 'published'
    WHERE id = v_req.offered_shift_id;

    -- Assign Recipient's Shift -> Requester
    UPDATE shifts 
    SET employee_id = v_req.requester_id, status = 'published'
    WHERE id = v_req.requested_shift_id;

    -- 3. Mark Request as Approved
    UPDATE shift_trade_requests 
    SET status = 'approved', reviewed_by = p_manager_id 
    WHERE id = p_request_id;

    RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_reservation_tables(p_reservation_id uuid, p_table_ids uuid[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$BEGIN
  UPDATE public.reservations
  SET assigned_table_ids = p_table_ids, updated_at = NOW()
  WHERE id = p_reservation_id
    AND merchant_id = user_merchant_id();
    -- AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found';
  END IF;

  RETURN json_build_object(
    'success', true,
    'reservation_id', p_reservation_id,
    'assigned_table_ids', p_table_ids
  );
END;$function$

CREATE OR REPLACE FUNCTION public.calculate_event_timing()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  last_event_time TIMESTAMPTZ;
BEGIN
  SELECT occurred_at INTO last_event_time
  FROM public.table_session_events
  WHERE session_id = NEW.session_id
    AND occurred_at < NEW.occurred_at
  ORDER BY occurred_at DESC
  LIMIT 1;

  IF last_event_time IS NOT NULL THEN
    NEW.minutes_since_previous := EXTRACT(EPOCH FROM (NEW.occurred_at - last_event_time)) / 60;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_modify_item(p_order_item_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_course_number INTEGER;
  v_course_status TEXT;
BEGIN
  -- Get item's order and course
  SELECT order_id, course_number INTO v_order_id, v_course_number
  FROM public.order_items
  WHERE id = p_order_item_id;

  IF v_order_id IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Check course status
  SELECT status INTO v_course_status
  FROM public.order_courses
  WHERE order_id = v_order_id AND course_number = v_course_number;

  -- Can modify if course doesn't exist yet or is still open
  RETURN v_course_status IS NULL OR v_course_status = 'open';
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_order(p_order_id uuid, p_cancel_reason text DEFAULT 'Customer cancelled'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_status TEXT;
  v_result JSON;
BEGIN
  -- Get order status
  SELECT status INTO v_order_status
  FROM public.orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- For draft/pending orders, we can cancel with lower permission
  IF v_order_status IN ('draft', 'pending') THEN
    -- Just need regular order manage permission
    -- IF NOT has_permission('location.orders.manage') THEN
    --   RAISE EXCEPTION 'Permission denied';
    -- END IF;

    -- Delete items (hard delete for draft)
    DELETE FROM public.order_item_modifiers oim
    USING public.order_items oi
    WHERE oim.order_item_id = oi.id AND oi.order_id = p_order_id;

    DELETE FROM public.order_items WHERE order_id = p_order_id;

    -- Update order to cancelled
    UPDATE public.orders
    SET 
      status = 'cancelled',
      void_reason = p_cancel_reason,
      updated_at = NOW()
    WHERE id = p_order_id;

    -- Close table session if linked
    UPDATE public.table_sessions
    SET 
      is_active = FALSE,
      status = 'available',
      closed_at = NOW()
    WHERE order_id = p_order_id AND is_active = TRUE;

    SELECT json_build_object(
      'success', true,
      'order_id', p_order_id,
      'action', 'cancelled',
      'reason', p_cancel_reason
    ) INTO v_result;

    RETURN v_result;
  ELSE
    -- For confirmed orders, use void_order
    RETURN public.void_order(p_order_id, p_cancel_reason);
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_merchant_access(target_merchant_id uuid, required_permission text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_clerk_user_id TEXT;
    merchant_clerk_org_id TEXT;
    carrier_id_lookup UUID;
    user_role_code TEXT;
BEGIN
    -- 1. Get Current User
    current_clerk_user_id := get_my_claim('sub')::text; -- Or use your request_user_id() helper
    IF current_clerk_user_id IS NULL THEN RETURN FALSE; END IF;

    -- 2. DEXA HQ OVERRIDE (Manage Everything)
    -- Replace with your actual HQ Org ID check or is_dexa_admin() function
    IF is_dexapos_admin()
    THEN
        RETURN TRUE;
    END IF;

    -- 3. Get Merchant Context (Clerk Org ID & Carrier ID)
    SELECT clerk_org_id, carrier_id INTO merchant_clerk_org_id, carrier_id_lookup
    FROM merchants
    WHERE id = target_merchant_id;

    -- 4. CARRIER OVERRIDE (Manage their merchants)
    IF EXISTS (
        SELECT 1 FROM members m
        JOIN carriers c ON c.clerk_org_id = m.organization_id
        WHERE m.user_id = current_clerk_user_id
        AND c.id = carrier_id_lookup
        -- Optional: Check if carrier member has specific carrier permissions here
    ) THEN
        RETURN TRUE;
    END IF;

    -- 5. MERCHANT ACCESS CHECK
    -- Get the user's role within this specific merchant
    SELECT role INTO user_role_code
    FROM members
    WHERE user_id = current_clerk_user_id
    AND organization_id = merchant_clerk_org_id;

    IF user_role_code IS NULL THEN
        RETURN FALSE; -- Not a member of this merchant
    END IF;

    -- If no specific permission is required (Read-Only access), basic membership is enough
    IF required_permission IS NULL THEN
        RETURN TRUE;
    END IF;

    -- 6. PERMISSION CHECK (Dynamic)
    -- specific override for your requirement: Owner/Admin always allow
    IF user_role_code IN ('merchant.owner', 'merchant.admin') THEN
        RETURN TRUE;
    END IF;

    -- Check if the user's role maps to the required permission code
    RETURN EXISTS (
        SELECT 1 FROM role_permissions
        WHERE role_code = user_role_code
        AND permission_code = required_permission
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_modifier_group_usage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_usage_count INTEGER;
    v_is_location_specific BOOLEAN;
BEGIN
    -- Check if this is a location-specific group
    SELECT (location_id IS NOT NULL) INTO v_is_location_specific
    FROM modifier_groups WHERE id = OLD.id;

    -- Only check usage for location-specific groups
    -- Global groups can always be deleted (they cascade to overrides)
    IF v_is_location_specific THEN
        -- Count how many menu items use this modifier group
        SELECT COUNT(*) INTO v_usage_count
        FROM menu_item_modifier_groups
        WHERE modifier_group_id = OLD.id;

        IF v_usage_count > 0 THEN
            RAISE EXCEPTION
                'Cannot delete location-specific modifier group: assigned to % menu item(s). Please unassign it from all menu items first.',
                v_usage_count;
        END IF;
    END IF;

    RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_schedule_usage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_usage_count INTEGER;
    v_is_location_specific BOOLEAN;
BEGIN
    -- Check if this is a location-specific schedule
    SELECT (location_id IS NOT NULL) INTO v_is_location_specific
    FROM schedules WHERE id = OLD.id;

    -- Only check usage for location-specific schedules
    -- Global schedules can always be deleted (they cascade to overrides)
    IF v_is_location_specific THEN
        -- Count how many categories/menus use this schedule
        SELECT
            (SELECT COUNT(*) FROM category_schedules WHERE schedule_id = OLD.id) +
            (SELECT COUNT(*) FROM menu_schedules WHERE schedule_id = OLD.id)
        INTO v_usage_count;

        IF v_usage_count > 0 THEN
            RAISE EXCEPTION
                'Cannot delete location-specific schedule: assigned to % menu(s) or category(ies). Please unassign it first.',
                v_usage_count;
        END IF;
    END IF;

    RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_order_item_instructions(p_order_item_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_result JSON;
BEGIN
  -- Verify access
  SELECT oi.order_id INTO v_order_id
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be modified';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Clear instructions
  UPDATE public.order_items
  SET 
    special_instructions = NULL,
    updated_at = NOW()
  WHERE id = p_order_item_id;

  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'special_instructions', NULL
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_order_items(p_order_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_status TEXT;
  v_removed_count INTEGER;
  v_result JSON;
BEGIN
  -- Verify order and status
  SELECT status INTO v_order_status
  FROM public.orders
  WHERE id = p_order_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  IF v_order_status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'Cannot clear items from % orders', v_order_status;
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Delete all modifiers
  DELETE FROM public.order_item_modifiers oim
  USING public.order_items oi
  WHERE oim.order_item_id = oi.id AND oi.order_id = p_order_id;

  -- Delete all items
  DELETE FROM public.order_items WHERE order_id = p_order_id;

  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  -- Reset order totals
  UPDATE public.orders
  SET 
    subtotal = 0,
    tax_amount = 0,
    total_amount = 0,
    updated_at = NOW()
  WHERE id = p_order_id;

  SELECT json_build_object(
    'success', true,
    'order_id', p_order_id,
    'removed_count', v_removed_count
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_floor_plan(p_location_id uuid, p_name text, p_description text DEFAULT NULL::text, p_canvas_width integer DEFAULT 1200, p_canvas_height integer DEFAULT 800, p_is_default boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_merchant_id UUID;
  v_floor_plan_id UUID;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.floor_plan.manage', 'merchant.settings.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied: location.floor_plan.manage required';
  -- END IF;

  -- Get merchant ID
  v_merchant_id := user_merchant_id();

  -- Verify location access
  IF NOT p_location_id = ANY(user_location_ids()) THEN
    RAISE EXCEPTION 'Location access denied';
  END IF;

  -- If setting as default, unset others
  IF p_is_default THEN
    UPDATE public.floor_plans 
    SET is_default = FALSE 
    WHERE location_id = p_location_id;
  END IF;

  -- Create floor plan
  INSERT INTO public.floor_plans (
    merchant_id, location_id, name, description,
    canvas_width, canvas_height, is_default,
    created_by
  ) VALUES (
    v_merchant_id, p_location_id, p_name, p_description,
    p_canvas_width, p_canvas_height, p_is_default,
    user_staff_profile_id()
  )
  RETURNING id INTO v_floor_plan_id;

  RETURN json_build_object(
    'success', true,
    'floor_plan_id', v_floor_plan_id,
    'name', p_name
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_confirmation_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result TEXT := 'RES-';
BEGIN
  FOR i IN 1..6 LOOP
    result := result || SUBSTR(chars, FLOOR(RANDOM() * LENGTH(chars) + 1)::INT, 1);
  END LOOP;
  NEW.confirmation_number := result;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_order_number(p_location_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_sequence_number INTEGER;
  v_date_str TEXT;
  v_order_number TEXT;
BEGIN
  -- Verify user has access to location
  IF NOT (p_location_id = ANY(user_location_ids())) THEN
    RAISE EXCEPTION 'Access denied: User does not have access to location';
  END IF;

  -- Get current date string (YYYYMMDD)
  v_date_str := TO_CHAR(CURRENT_DATE, 'YYYYMMDD');

  -- Get and increment sequence for today
  INSERT INTO public.order_sequences (location_id, sequence_date, last_order_number)
  VALUES (p_location_id, CURRENT_DATE, 1)
  ON CONFLICT (location_id, sequence_date)
  DO UPDATE SET last_order_number = order_sequences.last_order_number + 1
  RETURNING last_order_number INTO v_sequence_number;

  -- Format: ORD-YYYYMMDD-XXXX (e.g., ORD-20240101-0042)
  v_order_number := 'ORD-' || v_date_str || '-' || LPAD(v_sequence_number::TEXT, 4, '0');

  RETURN v_order_number;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_time_clock(p_pin_code text, p_location_id uuid, p_action_type text, p_device_id text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
    v_staff_id uuid;
    v_rate numeric;
    v_merchant_id uuid;
    v_current_shift_id uuid;
    v_current_status text;
    v_result json;
BEGIN
    -- 1. Validate PIN & Get Staff Context (Updated for Bcrypt)
    SELECT sm.staff_profile_id, sm.hourly_rate, sm.merchant_id
    INTO v_staff_id, v_rate, v_merchant_id

    FROM location_members sm
    WHERE sm.location_id = p_location_id 
      AND sm.is_active = true
      -- CRITICAL CHANGE: Validate the plain text PIN against the Bcrypt hash
      AND replace(sm.pin_code, '$2b$', '$2a$') = crypt(p_pin_code, replace(sm.pin_code, '$2b$', '$2a$'));

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid PIN code';
    END IF;

    -- 2. Find Active Shift (if any)
    SELECT id, status INTO v_current_shift_id, v_current_status
    FROM staff_shifts
    WHERE staff_profile_id = v_staff_id
      AND status != 'completed'
    ORDER BY created_at DESC
    LIMIT 1;

    -- 3. Handle Actions
    IF p_action_type = 'clock_in' THEN
        IF v_current_shift_id IS NOT NULL THEN
            RAISE EXCEPTION 'You are already clocked in!';
        END IF;

        INSERT INTO staff_shifts (
            merchant_id, location_id, staff_profile_id, 
            status, hourly_rate_snapshot, device_id
        ) VALUES (
            v_merchant_id, p_location_id, v_staff_id, 
            'active', COALESCE(v_rate, 0), p_device_id
        ) RETURNING id INTO v_current_shift_id;

        v_current_status := 'active';

    ELSIF p_action_type = 'clock_out' THEN
        IF v_current_shift_id IS NULL THEN
            RAISE EXCEPTION 'No active shift found to clock out from.';
        END IF;

        IF v_current_status = 'on_break' THEN
             RAISE EXCEPTION 'Please end your break before clocking out.';
        END IF;

        UPDATE staff_shifts
        SET status = 'completed',
            clock_out_time = now(),
            updated_at = now()
        WHERE id = v_current_shift_id;

        v_current_status := 'completed';

    ELSIF p_action_type = 'break_start' THEN
        IF v_current_status != 'active' THEN
             RAISE EXCEPTION 'Can only start break if active.';
        END IF;

        UPDATE staff_shifts
        SET status = 'on_break',
            break_logs = break_logs OR jsonb_build_object(
                'start', now(), 
                'end', null, 
                'type', 'unpaid'
            ),
            updated_at = now()
        WHERE id = v_current_shift_id;

        v_current_status := 'on_break';

    ELSIF p_action_type = 'break_end' THEN
        IF v_current_status != 'on_break' THEN
             RAISE EXCEPTION 'You are not on a break.';
        END IF;

        UPDATE staff_shifts
        SET status = 'active',
            break_logs = (
                SELECT jsonb_agg(
                    CASE 
                        WHEN (ordinality = jsonb_array_length(break_logs)) THEN 
                             elem OR jsonb_build_object('end', now())
                        ELSE elem 
                    END
                )
                FROM staff_shifts, jsonb_array_elements(break_logs) WITH ORDINALITY AS elem
                WHERE id = v_current_shift_id
            ),
            updated_at = now()
        WHERE id = v_current_shift_id;

        v_current_status := 'active';
    END IF;

    -- 4. Return Status for UI
    SELECT json_build_object(
        'success', true,
        'action', p_action_type,
        'status', v_current_status,
        'staff_id', v_staff_id,
        'shift_id', v_current_shift_id
    ) INTO v_result;

    RETURN v_result;
END;$function$

CREATE OR REPLACE FUNCTION public.merge_table_to_session(p_session_id uuid, p_table_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_position INTEGER;
BEGIN
  -- Verify session
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id AND is_active = TRUE
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  -- Check table is available
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = p_table_id AND ts.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'Table is already occupied';
  END IF;

  -- Get next position
  SELECT COALESCE(MAX(seated_position), 0) + 1 INTO v_position
  FROM public.table_session_tables
  WHERE session_id = p_session_id;

  -- Add table
  INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
  VALUES (p_session_id, p_table_id, FALSE, v_position);

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'merged_table_id', p_table_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.process_shift_pto_accrual()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_policy_id uuid;
    v_accrual_rate numeric;
    v_method text;
    v_hours_worked numeric;
    v_earned numeric;
BEGIN
    -- Only run when shift becomes 'completed'
    IF NEW.status = 'completed' AND (OLD.status != 'completed' OR OLD.status IS NULL) THEN

        -- 1. Get Employee's Policy
        SELECT p.id, p.accrual_rate, p.accrual_method
        INTO v_policy_id, v_accrual_rate, v_method
        FROM staff_profiles sp
        JOIN pto_policies p ON p.id = sp.pto_policy_id
        WHERE sp.id = NEW.employee_id;

        -- If no policy or not hourly, skip
        IF v_policy_id IS NULL OR v_method != 'hourly' THEN RETURN NEW; END IF;

        -- 2. Calculate Hours Worked (using actual clock times if available, else scheduled)
        v_hours_worked := EXTRACT(EPOCH FROM (NEW.end_time - NEW.start_time))/3600;

        -- 3. Calculate Earned Amount
        v_earned := v_hours_worked * v_accrual_rate;

        -- 4. Credit the Ledger
        INSERT INTO pto_ledger (
            merchant_id, 
            employee_id, 
            transaction_type, 
            amount, 
            source_shift_id, 
            description
        ) VALUES (
            NEW.merchant_id,
            NEW.employee_id,
            'accrual',
            v_earned,
            NEW.id,
            'Accrued from ' || round(v_hours_worked, 2) || 'h shift'
        );
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO public.order_status_history (
      order_id,
      from_status,
      to_status,
      changed_by_staff_id,
      changed_by_user_id,
      changed_at
    ) VALUES (
      NEW.id,
      OLD.status,
      NEW.status,
      NEW.created_by_staff_id,
      NEW.created_by_user_id,
      NOW()
    );

    -- Update timing fields based on status
    IF NEW.status = 'pending' AND NEW.sent_to_kitchen_at IS NULL THEN
      NEW.sent_to_kitchen_at = NOW();
    ELSIF NEW.status = 'preparing' AND NEW.started_preparing_at IS NULL THEN
      NEW.started_preparing_at = NOW();
    ELSIF NEW.status = 'ready' AND NEW.ready_at IS NULL THEN
      NEW.ready_at = NOW();
    ELSIF NEW.status = 'completed' AND NEW.completed_at IS NULL THEN
      NEW.completed_at = NOW();
    ELSIF NEW.status IN ('cancelled', 'void') AND NEW.cancelled_at IS NULL THEN
      NEW.cancelled_at = NOW();
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_session_event(p_session_id uuid, p_event_type session_event_type, p_notes text DEFAULT NULL::text, p_event_data jsonb DEFAULT '{}'::jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_event_id UUID;
BEGIN
  -- Verify session access
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found';
  END IF;

  INSERT INTO public.table_session_events (
    session_id, event_type, event_data, notes,
    triggered_by_staff_id, triggered_by_user_id
  ) VALUES (
    p_session_id, p_event_type, p_event_data, p_notes,
    user_staff_profile_id(), get_my_claim('sub')
  )
  RETURNING id INTO v_event_id;

  RETURN json_build_object(
    'success', true,
    'event_id', v_event_id,
    'event_type', p_event_type
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_order_item(p_order_item_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_order_status TEXT;
  v_item_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get order info and verify access
  SELECT 
    o.id,
    o.status,
    oi.subtotal
  INTO v_order_id, v_order_status, v_item_subtotal
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or access denied';
  END IF;

  -- Only allow hard delete on draft/pending orders
  -- Once order is confirmed/sent to kitchen, must use void_order_item
  IF v_order_status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'Cannot remove items from % orders. Use void_order_item() instead.', v_order_status;
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;

  -- Delete modifiers first (cascade would handle this, but being explicit)
  DELETE FROM public.order_item_modifiers
  WHERE order_item_id = p_order_item_id;

  -- Delete the item
  DELETE FROM public.order_items
  WHERE id = p_order_item_id;

  -- Return result
  SELECT json_build_object(
    'success', true,
    'removed_item_id', p_order_item_id,
    'order_id', v_order_id,
    'removed_subtotal', v_item_subtotal
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_order_item_modifier(p_modifier_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_item_id UUID;
  v_order_id UUID;
  v_item_quantity INTEGER;
  v_price_paid NUMERIC(10, 2);
  v_new_modifier_total NUMERIC(10, 2);
  v_new_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get modifier and item details
  SELECT 
    oim.order_item_id,
    oi.order_id,
    oi.quantity,
    oi.price_paid
  INTO v_order_item_id, v_order_id, v_item_quantity, v_price_paid
  FROM public.order_item_modifiers oim
  JOIN public.order_items oi ON oi.id = oim.order_item_id
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oim.id = p_modifier_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Modifier not found or cannot be removed';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Delete modifier
  DELETE FROM public.order_item_modifiers
  WHERE id = p_modifier_id;

  -- Calculate new totals
  SELECT COALESCE(SUM(total_price), 0)
  INTO v_new_modifier_total
  FROM public.order_item_modifiers
  WHERE order_item_id = v_order_item_id;

  v_new_subtotal := (v_item_quantity * v_price_paid) + (v_item_quantity * v_new_modifier_total);

  -- Update item subtotal
  UPDATE public.order_items
  SET 
    subtotal = v_new_subtotal,
    updated_at = NOW()
  WHERE id = v_order_item_id;

  SELECT json_build_object(
    'success', true,
    'removed_modifier_id', p_modifier_id,
    'order_item_id', v_order_item_id,
    'modifier_total', v_new_modifier_total,
    'new_subtotal', v_new_subtotal
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_order_items_batch(p_order_item_ids uuid[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_order_status TEXT;
  v_removed_count INTEGER := 0;
  v_item_id UUID;
  v_result JSON;
BEGIN
  -- Verify all items belong to same order and order is draft/pending
  SELECT DISTINCT o.id, o.status
  INTO v_order_id, v_order_status
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = ANY(p_order_item_ids)
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order items not found or access denied';
  END IF;

  IF v_order_status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'Cannot remove items from % orders', v_order_status;
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Delete modifiers for all items
  DELETE FROM public.order_item_modifiers
  WHERE order_item_id = ANY(p_order_item_ids);

  -- Delete items
  DELETE FROM public.order_items
  WHERE id = ANY(p_order_item_ids)
    AND is_voided = FALSE;

  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  SELECT json_build_object(
    'success', true,
    'order_id', v_order_id,
    'removed_count', v_removed_count,
    'removed_item_ids', p_order_item_ids
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_category_item_to_level(p_menu_item_id uuid, p_category_id uuid DEFAULT NULL::uuid, p_menu_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_target_level integer DEFAULT 1)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_deleted_levels TEXT[] := '{}';
BEGIN
    -- Reset Level 5 (location + menu + category)
    IF p_target_level < 5 AND p_location_id IS NOT NULL AND p_menu_id IS NOT NULL THEN
        DELETE FROM location_menu_item_overrides
        WHERE location_id = p_location_id 
          AND menu_id = p_menu_id 
          AND menu_item_id = p_menu_item_id
          AND (p_category_id IS NULL OR category_id = p_category_id);

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_5_location_menu');
        END IF;
    END IF;

    -- Reset Level 4 (location + category)
    IF p_target_level < 4 AND p_location_id IS NOT NULL AND p_category_id IS NOT NULL THEN
        DELETE FROM location_category_item_overrides
        WHERE location_id = p_location_id 
          AND category_id = p_category_id 
          AND menu_item_id = p_menu_item_id;

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_4_location_category');
        END IF;
    END IF;

    -- Reset Level 3 (category price) - only if merchant admin
    IF p_target_level < 3 AND p_location_id IS NULL AND p_category_id IS NOT NULL THEN
        UPDATE category_items
        SET custom_price = NULL, custom_cash_price = NULL, updated_at = NOW()
        WHERE category_id = p_category_id AND menu_item_id = p_menu_item_id;

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_3_category');
        END IF;
    END IF;

    -- Reset Level 2 (location item)
    IF p_target_level < 2 AND p_location_id IS NOT NULL THEN
        DELETE FROM location_item_overrides
        WHERE location_id = p_location_id AND menu_item_id = p_menu_item_id;

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_2_location_item');
        END IF;
    END IF;

    RETURN json_build_object(
        'success', true,
        'target_level', p_target_level,
        'deleted_overrides', v_deleted_levels
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_item_to_level(p_menu_item_id uuid, p_menu_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_target_level integer DEFAULT 1)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_deleted_levels TEXT[] := '{}';
BEGIN
    -- Reset Level 4 (location + menu override)
    IF p_target_level < 4 AND p_location_id IS NOT NULL AND p_menu_id IS NOT NULL THEN
        DELETE FROM location_menu_item_overrides
        WHERE location_id = p_location_id 
          AND menu_id = p_menu_id 
          AND menu_item_id = p_menu_item_id;

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_4_location_menu');
        END IF;
    END IF;

    -- Reset Level 3 (menu override) - only if merchant admin
    IF p_target_level < 3 AND p_location_id IS NULL AND p_menu_id IS NOT NULL THEN
        UPDATE menu_item_menus
        SET custom_price = NULL, custom_cash_price = NULL, updated_at = NOW()
        WHERE menu_id = p_menu_id AND menu_item_id = p_menu_item_id;

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_3_menu');
        END IF;
    END IF;

    -- Reset Level 2 (location item override)
    IF p_target_level < 2 AND p_location_id IS NOT NULL THEN
        DELETE FROM location_item_overrides
        WHERE location_id = p_location_id AND menu_item_id = p_menu_item_id;

        IF FOUND THEN
            v_deleted_levels := array_append(v_deleted_levels, 'level_2_location_item');
        END IF;
    END IF;

    RETURN json_build_object(
        'success', true,
        'target_level', p_target_level,
        'deleted_overrides', v_deleted_levels
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.seat_guests(p_table_ids uuid[], p_party_size integer, p_guest_name text DEFAULT NULL::text, p_guest_phone text DEFAULT NULL::text, p_guest_notes text DEFAULT NULL::text, p_reservation_id uuid DEFAULT NULL::uuid, p_waitlist_id uuid DEFAULT NULL::uuid, p_create_order boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_merchant_id UUID;
  v_location_id UUID;
  v_session_id UUID;
  v_order_id UUID;
  v_table_id UUID;
  v_is_first BOOLEAN := TRUE;
  v_server_staff_id UUID;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.tables.manage', 'location.orders.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Get merchant and location from first table
  SELECT fpo.merchant_id, fpo.location_id
  INTO v_merchant_id, v_location_id
  FROM public.floor_plan_objects fpo
  WHERE fpo.id = p_table_ids[1]
    AND fpo.merchant_id = user_merchant_id()
    AND fpo.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Table not found or access denied';
  END IF;

  -- Check if any table is already occupied
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = ANY(p_table_ids) AND ts.is_active = TRUE
  ) THEN
    RAISE EXCEPTION 'One or more tables are already occupied';
  END IF;

  -- Get current server (staff pinned into this device)
  v_server_staff_id := user_staff_profile_id();

  -- Create session
  INSERT INTO public.table_sessions (
    merchant_id, location_id,
    party_size, guest_name, guest_phone, guest_notes,
    reservation_id, waitlist_id,
    server_staff_id, server_user_id,
    status, seated_at
  ) VALUES (
    v_merchant_id, v_location_id,
    p_party_size, p_guest_name, p_guest_phone, p_guest_notes,
    p_reservation_id, p_waitlist_id,
    v_server_staff_id, get_my_claim('sub'),
    'seated', NOW()
  )
  RETURNING id INTO v_session_id;

  -- Link tables to session
  FOREACH v_table_id IN ARRAY p_table_ids
  LOOP
    INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
    VALUES (v_session_id, v_table_id, v_is_first, 
            ARRAY_POSITION(p_table_ids, v_table_id) - 1);
    v_is_first := FALSE;
  END LOOP;

  -- Create initial event
  INSERT INTO public.table_session_events (session_id, event_type, triggered_by_staff_id, triggered_by_user_id)
  VALUES (v_session_id, 'seated', v_server_staff_id, get_my_claim('sub'));

  -- Update reservation if provided
  IF p_reservation_id IS NOT NULL THEN
    UPDATE public.reservations
    SET status = 'seated', seated_at = NOW(), seated_session_id = v_session_id
    WHERE id = p_reservation_id;
  END IF;

  -- Update waitlist if provided
  IF p_waitlist_id IS NOT NULL THEN
    UPDATE public.waitlist
    SET status = 'seated', seated_at = NOW(), seated_session_id = v_session_id,
        actual_wait_minutes = EXTRACT(EPOCH FROM (NOW() - created_at)) / 60
    WHERE id = p_waitlist_id;
  END IF;

  -- Create order if requested
  IF p_create_order THEN
    SELECT (public.create_order(
      p_merchant_id := v_merchant_id,
      p_location_id := v_location_id,
      p_order_type := 'dine_in',
      p_table_number := (SELECT name FROM public.floor_plan_objects WHERE id = p_table_ids[1]),
      p_customer_name := p_guest_name
    ))->>'order_id' INTO v_order_id;

    -- Link order to session
    UPDATE public.table_sessions
    SET order_id = v_order_id::UUID
    WHERE id = v_session_id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'session_id', v_session_id,
    'order_id', v_order_id,
    'table_ids', p_table_ids,
    'party_size', p_party_size,
    'guest_name', p_guest_name
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.seat_reservation(p_reservation_id uuid, p_table_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_reservation RECORD;
  v_table_ids UUID[];
  v_result JSON;
BEGIN
  -- Get reservation info
  SELECT * INTO v_reservation
  FROM public.reservations
  WHERE id = p_reservation_id
    AND merchant_id = user_merchant_id()
    AND location_id = ANY(user_location_ids())
    AND status IN ('pending', 'confirmed', 'reminded', 'arrived');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Reservation not found or not ready to seat';
  END IF;

  -- Use provided tables or assigned tables
  v_table_ids := COALESCE(p_table_ids, v_reservation.assigned_table_ids);

  IF v_table_ids IS NULL OR array_length(v_table_ids, 1) = 0 THEN
    RAISE EXCEPTION 'No tables specified for seating';
  END IF;

  -- Seat the guests
  SELECT public.seat_guests(
    p_table_ids := v_table_ids,
    p_party_size := v_reservation.party_size,
    p_guest_name := v_reservation.party_name,
    p_guest_phone := v_reservation.phone,
    p_guest_notes := v_reservation.notes || COALESCE(' | ' || v_reservation.special_requests, ''),
    p_reservation_id := p_reservation_id,
    p_create_order := TRUE
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_item_course(p_order_item_id uuid, p_course_number integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_current_course_status TEXT;
BEGIN
  -- Get order ID and verify access
  SELECT oi.order_id INTO v_order_id
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found';
  END IF;

  -- Check if target course is still open
  SELECT status INTO v_current_course_status
  FROM public.order_courses
  WHERE order_id = v_order_id AND course_number = p_course_number;

  -- If course exists and is fired, can't add to it
  IF v_current_course_status IS NOT NULL AND v_current_course_status != 'open' THEN
    RAISE EXCEPTION 'Course % is already fired and cannot be modified', p_course_number;
  END IF;

  -- Ensure course exists
  PERFORM public.ensure_course_exists(v_order_id, p_course_number);

  -- Update item
  UPDATE public.order_items
  SET course_number = p_course_number, updated_at = NOW()
  WHERE id = p_order_item_id;

  RETURN json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'course_number', p_course_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_working_course(p_order_id uuid, p_course_number integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_course_status TEXT;
BEGIN
  -- Ensure course exists and is open
  SELECT status INTO v_course_status
  FROM public.order_courses
  WHERE order_id = p_order_id AND course_number = p_course_number;

  IF v_course_status IS NOT NULL AND v_course_status != 'open' THEN
    RAISE EXCEPTION 'Cannot set working course to fired course %', p_course_number;
  END IF;

  -- Ensure course exists
  PERFORM public.ensure_course_exists(p_order_id, p_course_number);

  -- Update session
  UPDATE public.table_sessions
  SET working_course = p_course_number, updated_at = NOW()
  WHERE order_id = p_order_id AND is_active = TRUE;

  RETURN json_build_object(
    'success', true,
    'working_course', p_course_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.transfer_table_session(p_session_id uuid, p_new_table_ids uuid[], p_reason text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_old_table_ids UUID[];
  v_table_id UUID;
  v_is_first BOOLEAN := TRUE;
BEGIN
  -- Verify permission
  -- IF NOT has_any_permission(ARRAY['location.tables.manage', 'merchant.orders.manage']) THEN
  --   RAISE EXCEPTION 'Permission denied';
  -- END IF;

  -- Verify session exists and is active
  IF NOT EXISTS (
    SELECT 1 FROM public.table_sessions
    WHERE id = p_session_id
      AND is_active = TRUE
      AND merchant_id = user_merchant_id()
      AND location_id = ANY(user_location_ids())
  ) THEN
    RAISE EXCEPTION 'Session not found or not active';
  END IF;

  -- Check new tables are available
  IF EXISTS (
    SELECT 1 FROM public.table_session_tables tst
    JOIN public.table_sessions ts ON ts.id = tst.session_id
    WHERE tst.table_id = ANY(p_new_table_ids) 
      AND ts.is_active = TRUE
      AND ts.id != p_session_id
  ) THEN
    RAISE EXCEPTION 'One or more target tables are occupied';
  END IF;

  -- Get old table IDs for reference
  SELECT ARRAY_AGG(table_id) INTO v_old_table_ids
  FROM public.table_session_tables
  WHERE session_id = p_session_id;

  -- Remove old table links
  DELETE FROM public.table_session_tables
  WHERE session_id = p_session_id;

  -- Add new table links
  FOREACH v_table_id IN ARRAY p_new_table_ids
  LOOP
    INSERT INTO public.table_session_tables (session_id, table_id, is_primary, seated_position)
    VALUES (p_session_id, v_table_id, v_is_first, 
            ARRAY_POSITION(p_new_table_ids, v_table_id) - 1);
    v_is_first := FALSE;
  END LOOP;

  -- Update order table number if linked
  UPDATE public.orders o
  SET table_number = (SELECT name FROM public.floor_plan_objects WHERE id = p_new_table_ids[1])
  FROM public.table_sessions ts
  WHERE ts.id = p_session_id AND o.id = ts.order_id;

  -- Record transfer event
  INSERT INTO public.table_session_events (
    session_id, event_type, notes, event_data,
    triggered_by_staff_id, triggered_by_user_id
  ) VALUES (
    p_session_id, 'custom', p_reason,
    jsonb_build_object(
      'action', 'table_transfer',
      'from_tables', v_old_table_ids,
      'to_tables', p_new_table_ids
    ),
    user_staff_profile_id(), get_my_claim('sub')
  );

  RETURN json_build_object(
    'success', true,
    'session_id', p_session_id,
    'from_table_ids', v_old_table_ids,
    'to_table_ids', p_new_table_ids
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_floor_plan_objects_batch(p_updates jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$DECLARE
  v_update JSONB;
  v_updated_count INTEGER := 0;
BEGIN
  FOR v_update IN SELECT * FROM jsonb_array_elements(p_updates)
  LOOP
    UPDATE public.floor_plan_objects
    SET 
      x = (v_update->>'x')::NUMERIC,
      y = (v_update->>'y')::NUMERIC,
      rotation = COALESCE((v_update->>'rotation')::NUMERIC, rotation),
      updated_at = NOW()
    WHERE id = (v_update->>'id')::UUID
      AND merchant_id = user_merchant_id();
      -- AND location_id = ANY(user_location_ids());
    RAISE LOG 'v_update %', v_update;

    IF FOUND THEN
      v_updated_count := v_updated_count + 1;
    END IF;
  END LOOP;

  RETURN json_build_object(
    'success', true,
    'updated_count', v_updated_count
  );
END;$function$

CREATE OR REPLACE FUNCTION public.update_order_item(p_order_item_id uuid, p_quantity integer DEFAULT NULL::integer, p_special_instructions text DEFAULT NULL::text, p_prep_station text DEFAULT NULL::text, p_course_number integer DEFAULT NULL::integer, p_price_override numeric DEFAULT NULL::numeric)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_current_quantity INTEGER;
  v_price_paid NUMERIC(10, 2);
  v_modifier_total NUMERIC(10, 2);
  v_new_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Get item details and verify access
  SELECT 
    oi.order_id,
    oi.quantity,
    oi.price_paid,
    COALESCE((
      SELECT SUM(oim.total_price)
      FROM public.order_item_modifiers oim
      WHERE oim.order_item_id = oi.id
    ), 0)
  INTO v_order_id, v_current_quantity, v_price_paid, v_modifier_total
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be modified';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;

  -- Handle price override (requires additional permission)
  IF p_price_override IS NOT NULL THEN
    IF NOT has_any_permission(ARRAY['location.orders.override_price', 'merchant.orders.manage']) THEN
      RAISE EXCEPTION 'Permission denied: price override requires manager permission';
    END IF;
    v_price_paid := p_price_override;
  END IF;

  -- Use provided quantity or keep current
  v_current_quantity := COALESCE(p_quantity, v_current_quantity);

  -- Validate quantity
  IF v_current_quantity < 1 THEN
    RAISE EXCEPTION 'Quantity must be at least 1';
  END IF;

  -- Calculate new subtotal
  v_new_subtotal := (v_current_quantity * v_price_paid) + (v_current_quantity * v_modifier_total);

  -- Update the item (only non-null fields)
  UPDATE public.order_items
  SET 
    quantity = v_current_quantity,
    price_paid = v_price_paid,
    subtotal = v_new_subtotal,
    special_instructions = COALESCE(p_special_instructions, special_instructions),
    prep_station = COALESCE(p_prep_station, prep_station),
    course_number = COALESCE(p_course_number, course_number),
    updated_at = NOW()
  WHERE id = p_order_item_id;

  -- Return result
  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'order_id', v_order_id,
    'quantity', v_current_quantity,
    'price_paid', v_price_paid,
    'modifier_total', v_modifier_total,
    'new_subtotal', v_new_subtotal,
    'special_instructions', p_special_instructions,
    'prep_station', p_prep_station,
    'course_number', p_course_number
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_order_item_quantity(p_order_item_id uuid, p_quantity integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_id UUID;
  v_price_paid NUMERIC(10, 2);
  v_modifier_total NUMERIC(10, 2);
  v_new_subtotal NUMERIC(10, 2);
  v_result JSON;
BEGIN
  -- Validate quantity
  IF p_quantity < 1 THEN
    RAISE EXCEPTION 'Quantity must be at least 1. Use void_order_item() to remove items.';
  END IF;

  -- Get item details and verify access
  SELECT 
    oi.order_id,
    oi.price_paid,
    COALESCE((
      SELECT SUM(oim.total_price)
      FROM public.order_item_modifiers oim
      WHERE oim.order_item_id = oi.id
    ), 0)
  INTO v_order_id, v_price_paid, v_modifier_total
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
    AND oi.is_voided = FALSE
    AND o.merchant_id = user_merchant_id()
    AND o.location_id = ANY(user_location_ids())
    AND o.status NOT IN ('completed', 'cancelled', 'void');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be modified';
  END IF;

  -- Verify permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;

  -- Calculate new subtotal
  v_new_subtotal := (p_quantity * v_price_paid) + (p_quantity * v_modifier_total);

  -- Update the item
  UPDATE public.order_items
  SET 
    quantity = p_quantity,
    subtotal = v_new_subtotal,
    updated_at = NOW()
  WHERE id = p_order_item_id;

  -- Return result
  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'order_id', v_order_id,
    'quantity', p_quantity,
    'price_paid', v_price_paid,
    'modifier_total', v_modifier_total,
    'new_subtotal', v_new_subtotal
  ) INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_has_location_permission(p_location_id uuid, p_permission_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
    v_user_id TEXT;
    v_merchant_id UUID;
    v_role_code TEXT;
BEGIN
    v_user_id := current_user_id();

    -- Fast path: check location membership first (most common case)
    SELECT lm.role_code, l.merchant_id 
    INTO v_role_code, v_merchant_id
    FROM location_members lm
    JOIN locations l ON l.id = lm.location_id
    WHERE lm.user_id = v_user_id
      AND lm.location_id = p_location_id
      AND lm.is_active = true;

    -- If user is a location member, check their role's permissions
    IF v_role_code IS NOT NULL THEN
        RETURN EXISTS (
            SELECT 1 FROM role_permissions
            WHERE role_code = v_role_code
              AND permission_code = p_permission_code
        );
    END IF;

    -- Fallback: get merchant_id and check if user is merchant admin
    IF v_merchant_id IS NULL THEN
        SELECT merchant_id INTO v_merchant_id 
        FROM locations WHERE id = p_location_id;
    END IF;

    -- Check if merchant admin (they have all location permissions)
    IF is_merchant_admin(v_merchant_id) THEN
        RETURN true;
    END IF;

    RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.void_order_item(p_order_item_id uuid, p_void_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_staff_id UUID;
  v_user_id TEXT;
  v_result JSON;
BEGIN
  -- Get current user
  v_user_id := get_my_claim('sub');

  -- Get staff_id if exists
  SELECT id INTO v_staff_id
  FROM public.staff_profiles
  WHERE user_id = v_user_id
  LIMIT 1;

  -- -- Verify user has permission
  -- IF NOT has_permission('location.orders.manage') THEN
  --   RAISE EXCEPTION 'Permission denied: location.orders.manage required';
  -- END IF;

  UPDATE public.order_items
  SET 
    is_voided = TRUE,
    void_reason = p_void_reason,
    voided_at = NOW(),
    voided_by = v_staff_id,
    updated_at = NOW()
  WHERE id = p_order_item_id
    AND is_voided = FALSE
    AND EXISTS (
      SELECT 1 FROM public.orders o
      WHERE o.id = order_items.order_id
        AND o.merchant_id = user_merchant_id()
        AND o.location_id = ANY(user_location_ids())
        AND o.status NOT IN ('completed', 'cancelled')
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order item not found or cannot be voided';
  END IF;

  SELECT json_build_object(
    'success', true,
    'order_item_id', p_order_item_id,
    'voided_at', NOW()
  ) INTO v_result;

  RETURN v_result;
END;
$function$
